def choose_job(jobs, now):
    best_key = None
    best_id = None
    for job in jobs:
        if job['arrival'] <= now and job['status'] == 'pending' and now + job['processing_time'] <= job['deadline']:
            key = (-job['priority'], job['deadline'], job['processing_time'], job['arrival'], job['id'])
            if best_key is None or key < best_key:
                best_key = key
                best_id = job['id']
    return best_id
